#!/bin/bash

#SBATCH --job-name=FD_C5_long_all
#SBATCH -o /mmfs1/home/ttryon/FLAMES_out/flame_%j_stdout
#SBATCH -e /mmfs1/home/ttryon/FLAMES_out/err_flame_%j_stdout
#SBATCH -N 2
#SBATCH --ntasks=256
#SBATCH --exclusive
#SBATCH --partition=compute-long
#SBATCH -t 100:00:00

# AIAA SciTech 2027: all 8 long-domain n-pentane runs (LONG in make_fuel_decks.py) packed into one 2-node job,
# 32 ranks each, run side by side as separate job steps (4 per node).
# Whole nodes (--exclusive); no memory requests (user, 2026-11-12).  Generated by make_fuel_decks.py.
# The job ends when the slowest run (Ms 1.47 with vaporization) finishes.  Each run's log: /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet/<case>.log

module purge
module load gnu9 mpich

mkdir -p /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet
cd /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet
srun --mpi=pmi2 --exclusive -N 1 -n 32 /home/ttryon/flames/bin/hydro2-2d-g++ /home/ttryon/flames/tests/AIAA2027/FuelDroplet/input_C5_D10um_Ms1.47_N100_vap_long > /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet/C5_D10um_Ms1.47_N100_vap_long.log 2>&1 &
srun --mpi=pmi2 --exclusive -N 1 -n 32 /home/ttryon/flames/bin/hydro2-2d-g++ /home/ttryon/flames/tests/AIAA2027/FuelDroplet/input_C5_D10um_Ms1.47_N100_long > /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet/C5_D10um_Ms1.47_N100_long.log 2>&1 &
srun --mpi=pmi2 --exclusive -N 1 -n 32 /home/ttryon/flames/bin/hydro2-2d-g++ /home/ttryon/flames/tests/AIAA2027/FuelDroplet/input_C5_D10um_Ms2_N100_vap_long > /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet/C5_D10um_Ms2_N100_vap_long.log 2>&1 &
srun --mpi=pmi2 --exclusive -N 1 -n 32 /home/ttryon/flames/bin/hydro2-2d-g++ /home/ttryon/flames/tests/AIAA2027/FuelDroplet/input_C5_D10um_Ms3_N100_vap_long > /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet/C5_D10um_Ms3_N100_vap_long.log 2>&1 &
srun --mpi=pmi2 --exclusive -N 1 -n 32 /home/ttryon/flames/bin/hydro2-2d-g++ /home/ttryon/flames/tests/AIAA2027/FuelDroplet/input_C5_D10um_Ms3_N100_vap_pair_long > /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet/C5_D10um_Ms3_N100_vap_pair_long.log 2>&1 &
srun --mpi=pmi2 --exclusive -N 1 -n 32 /home/ttryon/flames/bin/hydro2-2d-g++ /home/ttryon/flames/tests/AIAA2027/FuelDroplet/input_C5_D10um_Ms3_N100_pair_long > /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet/C5_D10um_Ms3_N100_pair_long.log 2>&1 &
srun --mpi=pmi2 --exclusive -N 1 -n 32 /home/ttryon/flames/bin/hydro2-2d-g++ /home/ttryon/flames/tests/AIAA2027/FuelDroplet/input_C5_D10um_Ms2_N100_long > /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet/C5_D10um_Ms2_N100_long.log 2>&1 &
srun --mpi=pmi2 --exclusive -N 1 -n 32 /home/ttryon/flames/bin/hydro2-2d-g++ /home/ttryon/flames/tests/AIAA2027/FuelDroplet/input_C5_D10um_Ms3_N100_long > /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/FuelDroplet/C5_D10um_Ms3_N100_long.log 2>&1 &
wait
